 flt=`<div class="fl wsr"><input type="search" placeholder="Cari nama / telepon / alamat / no meter…" aria-label="Cari pelanggan" value="${esc(S.wq||"")}" onchange="S.wq=this.value;S.lim=0;render()"><select aria-label="Filter status tagihan" onchange="S.wf=this.value;render()"><option value="belum"${fs==="belum"?" selected":""}>Belum ditagih</option><option value="sudah"${fs==="sudah"?" selected":""}>Sudah ditagih</option><option value="semua"${fs==="semua"?" selected":""}>Semua status</option></select>${nad>1?`<select aria-label="Urutan daftar" onchange="S.wo=this.value;render()"><option value="">Urut no meter</option><option value="alamat"${wo?" selected":""}>Kelompok per alamat</option></select>`:""}${(S.wq||"").trim()||fs!=="belum"?`<button class="b s" onclick="S.wq='';S.wf='';render()">Reset</button>`:""}</div>`,
 sm=(()=>{const bs=db.sales.filter(x=>x.bill&&x.bill.period===per&&x.status==="posted"&&(S.unit==="all"||x.unit_id===S.unit)),tb=bs.reduce((t,x)=>t+x.total,0),tp=bs.reduce((t,x)=>t+Math.min(paidOf(x),x.total),0);return bs.length?`<div class="wsm" aria-label="Ringkasan periode ${esc(per)}"><div><small>Tertagih</small><b>${rp(tb)}</b></div><div><small>Terbayar</small><b>${rp(tp)}</b><small>${tb>0?Math.round(tp/tb*100):0}%</small></div><div><small>Belum dibayar</small><b>${rp(Math.max(tb-tp,0))}</b></div></div>`:""})(),
