 if(e){if(db.water_readings.some(r=>r.conn_id===e._id)&&+e.initial!==a)throw fe("cn-a","Angka awal tidak bisa diubah setelah ada bacaan");e.meter_no=m;e.initial=a;e.installed=d;if($("#cn-g"))e.cls=v("cn-g");if($("#cn-ds"))e.disc=v("cn-ds");audit("update","water_connection",e._id,m);S.ecn=null;S.msg="Sambungan diperbarui"}
